const s = $input.item.json;
const total = Number(s.conversations_total) || 0;
const resolved = Number(s.conversations_resolved) || 0;
const waiting = Number(s.conversations_waiting) || 0;
const human = Number(s.conversations_human) || 0;
const resolutionRate = total > 0 ? Math.round((resolved / total) * 100) : 0;
const escalationRate = total > 0 ? Math.round(((waiting + human) / total) * 100) : 0;
const lkTotal = Number(s.learned_knowledge_total) || 0;
const lkActive = Number(s.learned_knowledge_active) || 0;
return [{
  json: {
    date: new Date().toISOString().slice(0, 10),
    conversations_total: total,
    conversations_resolved: resolved,
    escalation_rate_pct: escalationRate,
    resolution_rate_pct: resolutionRate,
    tickets_open: Number(s.tickets_open) || 0,
    learned_knowledge_total: lkTotal,
    learned_knowledge_active: lkActive,
    summary: `SupportLoop ${new Date().toISOString().slice(0,10)}: ${total} convs, ${resolutionRate}% résolution, ${escalationRate}% escalade, ${lkActive}/${lkTotal} connaissances actives.`
  }
}];

// TODO: stocker le snapshot dans une table analytics ou l'envoyer par email/webhook
// $input.item.json contient le rapport calculé
return $input.all();
